PREFIX in: <http://data.world/schema/insurance/>

SELECT ?agentId ?policyNumber ?claimNumber ?lossReserveAmount
WHERE {
  SERVICE <mapped> {
    ?policy in:soldByAgent ?agent ;
            in:policyNumber ?policyNumber .

    ?agent in:agentId ?agentId .

    ?coverage in:hasPolicy ?policy .

    ?claim in:against ?coverage ;
           in:claimNumber ?claimNumber ;
           in:hasLossReserve ?lossReserve .

    ?lossReserve in:lossReserveAmount ?lossReserveAmount .
  }
}
ORDER BY ?agentId ?policyNumber ?claimNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber ?agentId
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:policyNumber ?policyNumber ;
            in:soldByAgent ?agent .
    ?agent a in:Agent ;
           in:agentId ?agentId .
  }
}

PREFIX in: <http://data.world/schema/insurance/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?policyNumber (AVG(?settlementDays) AS ?averageTimeToSettleDays)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimOpenDate ?openDate ;
           in:claimCloseDate ?closeDate ;
           in:against ?coverage .

    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy .

    ?policy a in:Policy ;
            in:policyNumber ?policyNumber .

    BIND((xsd:dateTime(?closeDate) - xsd:dateTime(?openDate)) / "P1D"^^xsd:dayTimeDuration AS ?settlementDays)
  }
}
GROUP BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber
       (SUM(?lossPaymentVal + ?lossReserveVal + ?expensePaymentVal + ?expenseReserveVal) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:against ?coverage .

    ?coverage in:hasPolicy ?policy .
    ?policy in:policyNumber ?policyNumber .

    OPTIONAL {
      ?claim in:hasLossPayment ?lp .
      ?lp in:lossPaymentAmount ?lossPaymentAmount .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lr .
      ?lr in:lossReserveAmount ?lossReserveAmount .
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?ep .
      ?ep in:expensePaymentAmount ?expensePaymentAmount .
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?er .
      ?er in:expenseReserveAmount ?expenseReserveAmount .
    }

    BIND(COALESCE(xsd:decimal(?lossPaymentAmount), 0) AS ?lossPaymentVal)
    BIND(COALESCE(xsd:decimal(?lossReserveAmount), 0) AS ?lossReserveVal)
    BIND(COALESCE(xsd:decimal(?expensePaymentAmount), 0) AS ?expensePaymentVal)
    BIND(COALESCE(xsd:decimal(?expenseReserveAmount), 0) AS ?expenseReserveVal)
  }
}
GROUP BY ?policyNumber
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:hasExpenseReserve ?expenseReserve .
    ?expenseReserve in:expenseReserveAmount ?expenseReserveAmount .
  }
}
ORDER BY ?claimNumber
